package com.aliothmoon.maafw.once;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import org.junit.Test;import static org.junit.Assert.*;
/** Offline transport/predicate and source contracts, never a live UI action. */
public class AndroidRewardsEntryActorTest {
 static final String N="0123456789abcdef0123456789abcdef";
 private String source()throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/AndroidRewardsEntryActor.java"));}
 static class Sink extends OutputStream {int writes,flushes,closes,bytes;int fail;public void write(int b)throws IOException{bytes++;}public void write(byte[] b)throws IOException{writes++;bytes+=fail==1?3:b.length;if(fail==1)throw new IOException();}public void flush()throws IOException{flushes++;if(fail==2)throw new IOException();}public void close()throws IOException{closes++;if(fail==3)throw new IOException();}}
 @Test public void commandOnceThenEof()throws Exception{var c=new AndroidRewardsEntryActor.OneCommit();var s=new Sink();c.send(s,NativeRewardsEntryProtocol.commit(N).getBytes(StandardCharsets.US_ASCII));assertTrue(c.attempted());assertTrue(c.flushed());assertEquals(1,s.writes);assertEquals(1,s.flushes);assertEquals(1,s.closes);try{c.send(s,new byte[1]);fail();}catch(IOException expected){}assertEquals(1,s.writes);}
 @Test public void partialWriteCannotRetry()throws Exception{checkFailure(1,false);}
 @Test public void flushFailureCannotRetry()throws Exception{checkFailure(2,false);}
 @Test public void eofCloseFailureCannotRetry()throws Exception{checkFailure(3,true);}
 private void checkFailure(int fail,boolean flushed)throws Exception{var c=new AndroidRewardsEntryActor.OneCommit();var s=new Sink();s.fail=fail;try{c.send(s,new byte[40]);fail();}catch(IOException expected){}assertTrue(c.attempted());assertEquals(flushed,c.flushed());try{c.send(s,new byte[40]);fail();}catch(IOException expected){}assertEquals(1,s.writes);}
 @Test public void boundaryExpiredGateCannotDispatch(){assertTrue(AndroidRewardsEntryActor.dispatchAllowed(9,10,true,false,true,true));assertFalse(AndroidRewardsEntryActor.dispatchAllowed(10,10,true,false,true,true));assertFalse(AndroidRewardsEntryActor.dispatchAllowed(11,10,true,false,true,true));}
 @Test public void cancellationAndReplacementCannotDispatch(){assertFalse(AndroidRewardsEntryActor.dispatchAllowed(9,10,false,false,true,true));assertFalse(AndroidRewardsEntryActor.dispatchAllowed(9,10,true,true,true,true));assertFalse(AndroidRewardsEntryActor.dispatchAllowed(9,10,true,false,false,true));assertFalse(AndroidRewardsEntryActor.dispatchAllowed(9,10,true,false,true,false));}
 @Test public void fixedRequestBounds(){assertTrue(new AndroidRewardsEntryActor.Request(N,8,1440,2560,0,10001,10002,10003,60).valid());assertFalse(new AndroidRewardsEntryActor.Request(N,8,1440,2560,0,10001,10002,10003,8).valid());assertFalse(new AndroidRewardsEntryActor.Request("bad",8,1440,2560,0,10001,10002,10003,60).valid());assertFalse(new AndroidRewardsEntryActor.Request(N,8,8193,2560,0,10001,10002,10003,60).valid());assertFalse(new AndroidRewardsEntryActor.Request(N,8,1440,2560,4,10001,10002,10003,60).valid());}
 @Test public void framingRejectsExtraNewlineAndRawText(){byte[] p="ERP1|ABC|0123\n".getBytes(StandardCharsets.US_ASCII);assertTrue(AndroidRewardsEntryActor.validLine(p,p.length));for(String x:new String[]{"ERP1|ABC", "ERP1|ABC\n\n", "raw UI text\n", "ERP1|ABC\r\n"}){byte[] b=x.getBytes(StandardCharsets.US_ASCII);assertFalse(x,AndroidRewardsEntryActor.validLine(b,b.length));}}
 @Test public void badReceiptCannotQualify(){var r=new NativeRewardsEntryProtocol.Result(N,8,NativeRewardsEntryProtocol.Reason.OK,NativeRewardsEntryProtocol.Cleanup.CONFIRMED,true,true,10,20,21);assertTrue(result(r,AndroidRewardsEntryActor.FixedStatus.COMPLETE,true,true,true,22).succeeded());assertFalse(result(r,AndroidRewardsEntryActor.FixedStatus.PROTOCOL_REJECTED,true,true,true,22).succeeded());assertFalse(result(r,AndroidRewardsEntryActor.FixedStatus.COMPLETE,false,true,true,22).succeeded());assertFalse(result(r,AndroidRewardsEntryActor.FixedStatus.COMPLETE,true,false,true,22).succeeded());assertFalse(result(r,AndroidRewardsEntryActor.FixedStatus.COMPLETE,true,true,false,22).succeeded());assertFalse(result(r,AndroidRewardsEntryActor.FixedStatus.COMPLETE,true,true,true,-1).succeeded());}
 private AndroidRewardsEntryActor.Result result(NativeRewardsEntryProtocol.Result r,AndroidRewardsEntryActor.FixedStatus s,boolean clean,boolean attempted,boolean flushed,long at){return new AndroidRewardsEntryActor.Result(r,s,true,true,attempted,flushed,clean,true,true,true,0,150,at);}
 @Test public void fixedCommandOwnApkAndInheritedEnvironment()throws Exception{String s=source();assertTrue(s.contains("String apk=verifiedApk(context)"));assertTrue(s.contains("String[] command={\"/system/bin/app_process\",\"-cp\",apk,\"/system/bin\",HELPER"));assertTrue(s.contains("service.newProcess(command,null,null)"));assertEquals(1,s.split("service.newProcess",-1).length-1);assertFalse(s.contains("/system/bin/sh"));assertFalse(s.contains("/system/bin/env"));assertFalse(s.contains("CLASSPATH="));}
 @Test public void durableCommitCallbackBeforeAttemptAndLocalFinalCheck()throws Exception{String s=source();int gate=s.indexOf("commitGate.allowAndBurnNavigation(prepared)");int auth=s.indexOf("if(!authority(context))",gate);int binder=s.indexOf("same=binder==Shizuku.getBinder()",auth);int local=s.indexOf("dispatchAllowed(SystemClock.elapsedRealtime()",binder);int attempt=s.indexOf("commitAttempted=true",local);int send=s.indexOf("once.send(output,commitBytes)",attempt);assertTrue(gate>=0&&auth>gate&&binder>auth&&local>binder&&attempt>local&&send>attempt);}
 @Test public void quarantineIsCheckedAndNeverReset()throws Exception{String s=source();assertTrue(s.contains("status!=FixedStatus.COMPLETE||receipt==null||receipt.cleanup()==NativeRewardsEntryProtocol.Cleanup.UNKNOWN"));assertTrue(s.contains("return knownClean()&&AndroidUiStructureReader.processKnownClean()"));assertFalse(s.contains("quarantine=null"));assertTrue(s.contains("CLAIMED.compareAndSet(false,true)"));assertFalse(s.contains("CLAIMED.set(false)"));}
 @Test public void completeProtocolBeforeReceivedTimestampAndNoRawOutput()throws Exception{String s=source();assertTrue(s.indexOf("receivedAt=SystemClock.elapsedRealtime()")>s.indexOf("NativeRewardsEntryProtocol.parseResult"));assertTrue(s.contains("lineCount>=2"));assertTrue(s.contains("lineBytes!=0||receipt==null"));assertTrue(s.contains("if(stderr!=null){stderr.close();stderr=null;}"));for(String bad:new String[]{"System.out","Log.","printStackTrace","getMessage()","writeString","getWindows(","performAction("})assertFalse(bad,s.contains(bad));}
 @Test public void independentFdCleanupAndFixedPhaseCap()throws Exception{String s=source();assertTrue(s.contains("PHASE_MILLIS=30_000"));for(String stream:new String[]{"input","output","stdout","stdin","stderr"})assertTrue(stream,s.contains("try{if("+stream+"!=null)"+stream+".close();}catch(Exception ignored){allClosed=false;}"));}
 @Test public void selectorModeIsCompiledV48Only()throws Exception{String s=source();String gate="if(ReadOnlyCheckpoint.CURRENT==ReadOnlyCheckpoint.REWARDS_ENTRY_V48){";int a=s.indexOf(gate);assertTrue(a>s.indexOf("String[] command="));int b=s.indexOf("}",a);String mode=s.substring(a,b);assertTrue(mode.contains("command=Arrays.copyOf(command,command.length+1);"));assertTrue(mode.contains("command[command.length-1]=\"PARENT_REWARDS_V48\";"));assertEquals(1,s.split("PARENT_REWARDS_V48",-1).length-1);assertTrue(b<s.indexOf("if(!authority(context)||!live(current,deadline))",b));assertFalse(s.substring(s.indexOf("record Request("),s.indexOf("interface DispatchGate")).contains("selector"));}
 @Test public void originalTenHelperArgumentsRemainExact()throws Exception{String s=source().replace("\r\n","\n");String expected="String[] command={\"/system/bin/app_process\",\"-cp\",apk,\"/system/bin\",HELPER,request.nonce(),Long.toString(deadline),\n"+"                Integer.toString(request.task()),Integer.toString(request.width()),Integer.toString(request.height()),Integer.toString(request.rotation()),\n"+"                Integer.toString(request.bingUid()),Integer.toString(request.systemUiUid()),Integer.toString(request.ownUid()),Integer.toString(request.ownTask())};";assertTrue(s.contains(expected));int end=s.indexOf(expected)+expected.length();assertTrue(s.substring(end).startsWith("\n            if(ReadOnlyCheckpoint.CURRENT==ReadOnlyCheckpoint.REWARDS_ENTRY_V48){"));}
 @Test public void locateModeIsCompiledAndCannotAcceptMainPrepared()throws Exception{String s=source();int a=s.indexOf("if(ReadOnlyCheckpoint.CURRENT==ReadOnlyCheckpoint.UI_LOCATE_V52){");assertTrue(a>0);int b=s.indexOf("}",a);assertTrue(s.substring(a,b).contains("command[command.length-1]=\"SHOW_REGION_V52\";"));assertEquals(1,s.split("SHOW_REGION_V52",-1).length-1);assertTrue(s.contains("frame.startsWith(ReadOnlyCheckpoint.CURRENT==ReadOnlyCheckpoint.UI_LOCATE_V52?\"ERP2|\":\"ERP1|\")"));assertTrue(s.contains("?NativeRewardsEntryProtocol.parseTemplatePrepared("));assertTrue(s.contains(":NativeRewardsEntryProtocol.parsePrepared("));for(String old:new String[]{"UI_READY_V49","UI_FORMAT_V50","UI_FIELD_V51"})assertTrue(s.contains("ReadOnlyCheckpoint.CURRENT==ReadOnlyCheckpoint."+old));}
}
